            hostDeniedCount: workspaceReads.hostDeniedCount,
            hostDenied: workspaceReads.hostDenied,
            hostCacheRoot: workspaceReads.hostCacheRoot,
            hostCacheCount: workspaceReads.hostCacheCount,
            hostCacheReads: workspaceReads.hostCacheReads,
            hostTempRoot: workspaceReads.hostTempRoot,
            hostTempCount: workspaceReads.hostTempCount,
            hostTempReads: workspaceReads.hostTempReads,
            armWorldRoot: workspaceReads.armWorldRoot,
            armWorldCount: workspaceReads.armWorldCount,
            armWorldReads: workspaceReads.armWorldReads,
            allowRead: workspaceReads.allowRead,
