          restoreProven: removal.restoreProven === true,
          restoreAttempted: removal.restoreAttempted === true,
          restoreNotExercised: removal.restoreNotExercised === true,
          restoredRecallIds: removal.restore.restoredRecallIds,
          callIdOnlyRecallIds: removal.callIdOnlyRecallIds,
          notApplicable: removal.notApplicable ?? [],
