      notApplicableReasons: notApplicableReasonTotals,
      restoreNotExercised: removal.restoreNotExercised === true,
      restoreAttempted: removal.restoreAttempted === true,
      absenceScope: removalAbsenceScopeLabel(removal.absenceScope),
      /** The host checkpoint's post-segment re-carry, disclosed by count and request. */
      checkpointCarried: removal.checkpointCarried ?? null,
      returnedPastSegment: removal.returnedPastSegment ?? null,
      /** The 1d correction: main-request scope, ledger denominator, ask disclosure. */
